function normalizeLooseText(value) {
  return String(value || '')
    .toLowerCase()
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '');
}

function hasPersonalTargetPayload(payload) {
  return Boolean(
    payload?.id ||
    payload?.taskId ||
    payload?.reminderId ||
    payload?.eventId ||
    payload?.query ||
    payload?.target ||
    payload?.targetTitle ||
    payload?.currentTitle ||
    payload?.originalTitle ||
    payload?.title ||
    payload?.task ||
    payload?.reminder ||
    payload?.event
  );
}

function inferPersonalQueryFromText(text) {
  const normalized = normalizeLooseText(text);
  const patterns = [
    ['turno', /\bturnos?\b/],
    ['cita', /\bcitas?\b/],
    ['reunion', /\breuniones?\b|\breunion\b/],
    ['agenda', /\bagenda\b|\beventos?\b/],
    ['recordatorio', /\brecordatorios?\b/],
    ['tarea', /\btareas?\b/]
  ];
  const match = patterns.find(([, pattern]) => pattern.test(normalized));
  return match ? match[0] : '';
}

